#pragma once
#include "motion.hpp"
#include <cstdint>
#include <nlohmann/json.hpp>

namespace motion::dex2hoi {
// Fixed batch-one HUMOTO graph contract. Motion is model-major [429,T];
// prefix is normalized and is never resampled or regenerated by this sampler.
struct Conditions {
    std::vector<float> prefix,text,objects;
    std::array<bool,2> object_mask{true,true};
    std::array<float,72> init_features{};
    std::array<float,3> root_x0{};
    std::array<float,6> obj_x0{};
};
struct SamplingOptions {
    uint32_t seed=0;
    unsigned steps=500;
    float guidance=2.5f;
};
// Explicitly serialized sampling schedule. Each index refers to the original
// 500-step training schedule, including both endpoints when steps > 1.
std::vector<int64_t> sampling_timesteps(unsigned steps);
std::array<double,500> cosine_alphas();
std::vector<float> ddim_step(std::span<const float> x,std::span<const float> x0,
                             double alpha,double previous_alpha);

class Context {
    struct Impl;
    std::unique_ptr<Impl> impl;
public:
    explicit Context(const fs::path& bundle,unsigned threads=4);
    ~Context();
    Context(const Context&)=delete;
    Context& operator=(const Context&)=delete;
    std::vector<float> text(const std::string&,std::vector<int64_t>* tokens=nullptr);
    // Two explicitly sampled point clouds, each 128 xyz points in object space.
    // Output is projected geometry conditioning, before the graph's type token.
    std::vector<float> objects(std::span<const float> points);
    std::vector<float> denoise(std::span<const float> x,int64_t timestep,
                               const Conditions&,float text_scale=1);
    // Returns [429,60] normalized predictions, excluding the untouched prefix.
    std::vector<float> sample(const Conditions&,const SamplingOptions&,nlohmann::json& recipe);
    const nlohmann::json& manifest() const;
    const std::string& manifest_sha256() const;
};
int command(const std::vector<std::string>&);
const char* help();
}
